function check($v,$label){if(!$v)throw new Exception($label);$GLOBALS['checks']++;}
function is_wp_error($v){return $v instanceof WP_Error;} function get_current_user_id(){return $GLOBALS['uid'];} function wp_get_current_user(){return $GLOBALS['users'][$GLOBALS['uid']]??new WP_User(0,'','',[]);}
