function wp_set_password($p,$id){$GLOBALS['passwords'][$id]=$p;} function wp_generate_password($n,$s=true,$x=false){return str_repeat('x',$n);} function get_option($k,$d=false){return $GLOBALS['options'][$k]??$d;} function add_option($k,$v,...$args){if(isset($GLOBALS['options'][$k]))return false;$GLOBALS['options'][$k]=$v;return true;} function delete_option($k){$exists=isset($GLOBALS['options'][$k]);unset($GLOBALS['options'][$k]);return $exists;}
function get_field($k,$id,$format=true){return $GLOBALS['fields'][$id][$k]??null;} function get_fields($id){return $GLOBALS['fields'][$id]??[];} function update_field($k,$v,$id){$GLOBALS['fields'][$id][$k]=$v;} function get_post($id){return $GLOBALS['posts'][$id]??null;}
function delete_post_meta($id,$k){unset($GLOBALS['fields'][$id][$k]);} function sanitize_text_field($s){return trim(strip_tags($s));} function sanitize_email($s){return $s;} function is_email($s){return filter_var($s,FILTER_VALIDATE_EMAIL);} function email_exists($s){return false;}
